def drive(me, enemy, arena):
    if not me.can_drive:
        return (0, 0)
    b = bearing_to(enemy.x, enemy.y)
    turn = b / 180.0
    if turn > 1:
        turn = 1
    if turn < -1:
        turn = -1
    f = 1.0 - abs(turn) * 0.5
    if f < 0.3:
        f = 0.3
    left = f - turn
    right = f + turn
    if left > 1:
        left = 1
    if left < -1:
        left = -1
    if right > 1:
        right = 1
    if right < -1:
        right = -1
    return (left, right)

def weapons(me, enemy, arena):
    cmds = []
    w = me.weapons.get("front")
    if w is not None and w.get("type") == "spinner":
        target = w.get("max_rpm")
        if target is None:
            target = 2000
        cmds.append(spin("front", target))
    return cmds

def drive(me, enemy, arena):
    d = distance_to(enemy.x, enemy.y)
    b = bearing_to(enemy.x, enemy.y)
    t = b / 30.0
    if t > 1.0:
        t = 1.0
    elif t < -1.0:
        t = -1.0
    if d > 2.0:
        f = 1.0
    elif d > 0.9:
        f = (d - 0.9) / 1.1
    else:
        f = 0.25
    l = f - t
    r = f + t
    if l > 1.0:
        l = 1.0
    elif l < -1.0:
        l = -1.0
    if r > 1.0:
        r = 1.0
    elif r < -1.0:
        r = -1.0
    np = me.memory.get("np")
    if np is None or arena.time >= np:
        me.memory["np"] = arena.time + 2.0
        print(f"t={arena.time:.1f} d={d:.2f} b={b:.0f} hp={me.health:.2f} eh={enemy.health:.2f}")
    return (l, r)

